comp=str.maketrans('ACGTN','TGCAN'); seq2i={s:i for i,s in enumerate(lib.sequence)}; mats={}
for fn in sorted(glob.glob('/task/input/fastq/*.gz')):
 x=np.zeros(len(lib),int)
 with gzip.open(fn,'rt') as f:
  while True:
   h=f.readline()
   if not h: break
   s=f.readline().strip(); f.readline(); f.readline(); p=s.find('GTTTTAGAGCTA')
   if p>=20:
    k=seq2i.get(s[p-20:p]);
    if k is not None:x[k]+=1
